<script lang="ts">
  import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import type { OnValueChange } from '../shared/types.js'; import { composeEventHandlers } from '../shared/events.js'; import { getMenuContext, MenuCheckboxState, setMenuCheckboxContext, type MenuItemRecord } from './menu-context.svelte.js';
  interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; checked?: boolean; onCheckedChange?: OnValueChange<boolean, 'item-press'>; disabled?: boolean; closeOnClick?: boolean; textValue?: string; ref?: HTMLDivElement | null; }
  let { children, checked = $bindable(false), onCheckedChange, disabled = false, closeOnClick = false, textValue = '', ref = $bindable(null), onclick, ...rest }: Props = $props(); const menu = getMenuContext(); const checkbox = setMenuCheckboxContext(new MenuCheckboxState()); $effect.pre(() => { checkbox.checked = checked; }); $effect(() => { if (!ref) return; const item: MenuItemRecord = { element: ref, disabled, text: textValue || ref.textContent?.trim() || '' }; return menu.register(item); });
  function select(event: Event) { if (disabled) return; checked = !checked; onCheckedChange?.(checked, { reason: 'item-press', event }); if (!closeOnClick) event.preventDefault(); }
</script>
<div bind:this={ref} {...rest} role="menuitemcheckbox" tabindex="-1" aria-checked={checked} aria-disabled={disabled || undefined} data-checked={checked ? '' : undefined} data-disabled={disabled ? '' : undefined} onclick={composeEventHandlers(onclick, select)}>{@render children?.()}</div>
